/**
 * THE ROUTE TABLE. One row per screen, in the mock's navigation order.
 *
 * Screen agents: DO NOT EDIT THIS FILE to build your screen. Your screen already
 * has a row here and a stub file at src/screens/<Id>.tsx — replace the body of
 * that file and nothing else. Touch this table only to change a path, a nav
 * group, an icon or a role requirement, and say so in your report.
 *
 * `titleKey` / `navKey` are catalog keys (packages/config/locales/{tr,en}.json).
 * Every one of them must exist in BOTH locales or the app throws on render;
 * test/i18n.test.ts asserts that for the whole table.
 */

export type NavGroup = "monitor" | "work" | "governance" | "admin";

export interface ScreenDef {
  /** Matches the mock's view id; also the stub component's file name, lowercased. */
  readonly id: string;
  /** Route path relative to the shell root, without a leading slash. */
  readonly path: string;
  /** Catalog key for the page heading. */
  readonly titleKey: string;
  /** Catalog key for the sidebar label; absent means "not in the sidebar". */
  readonly navKey?: string;
  readonly group?: NavGroup;
  /** Glyph from the mock's NAV table. */
  readonly icon?: string;
  /**
   * Roles that may SEE this entry in the navigation. Empty/absent = everyone.
   * This is a usability filter, NOT access control — the BFF authorises every
   * request regardless of what the sidebar shows. See RequireSession.tsx.
   */
  readonly roles?: readonly string[];
}

export const NAV_GROUPS: readonly NavGroup[] = ["monitor", "work", "governance", "admin"];

export const NAV_GROUP_KEY: Readonly<Record<NavGroup, string>> = {
  monitor: "nav.group.monitor",
  work: "nav.group.work",
  governance: "nav.group.governance",
  admin: "nav.group.admin",
};

